def _load_benchmark_data(self, ctx: SystemContext) -> None:
    """Load cached CUTLASS benchmark data into context."""
    try:
        from acceleration.cutlass_integration import load_cached_benchmarks
    except ImportError:
        return

    cache = load_cached_benchmarks()
    if cache is None:
        return

    if not cache.is_valid(ctx.gpu_name, ctx.driver_version):
        logger.info("Benchmark cache stale (hardware/driver changed or expired)")
        return

    # Compute summary metrics: peak efficiency per precision
    peak_efficiency: dict[str, float] = {}
    mem_bw = 0.0
    for r in cache.results:
        if r.precision == "memory_bandwidth":
            mem_bw = r.efficiency_pct * 1008.0 / 100  # convert back to GB/s
            continue
        if r.precision not in peak_efficiency or r.efficiency_pct > peak_efficiency[r.precision]:
            peak_efficiency[r.precision] = r.efficiency_pct

    ctx.benchmark_data = {
        "peak_efficiency": peak_efficiency,
        "memory_bandwidth_gbs": mem_bw,
        "result_count": len(cache.results),
        "cache_gpu": cache.gpu_name,
    }
    logger.info(
        "Loaded benchmark data: %d results, peak efficiencies: %s",
        len(cache.results),
        {k: f"{v:.0f}%" for k, v in sorted(peak_efficiency.items())},
    )

